    private func validateAndStripPKCS7(_ plaintext: Data) -> Result<Data, ContractError> {
        guard plaintext.count > 0 && plaintext.count % blockSize == 0 else {
            return .failure(.invalidPayload)
        }

        let paddingByte = plaintext[plaintext.count - 1]
        let paddingLength = Int(paddingByte)

        guard paddingLength > 0 && paddingLength <= blockSize else {
            return .failure(.paddingInvalid)
        }

        // Validate all padding bytes
        for i in (plaintext.count - paddingLength)..<plaintext.count {
            if plaintext[i] != paddingByte {
                return .failure(.paddingInvalid)
            }
        }

        let strippedData = plaintext.prefix(plaintext.count - paddingLength)
        return .success(Data(strippedData))
    }

    // MARK: - CBC Decryption
    private func decryptCBC(ciphertext: Data, iv: Data) -> Result<Data, ContractError> {
        guard ciphertext.count % blockSize == 0 else {
