// MARK: - Reverse Proxy Response Handler
// The proxy maps contract errors to HTTP responses
struct ProxyResponseMapper {

    /// Maps contract execution results to HTTP response codes
    /// Note: The proxy preserves distinct error codes for client debugging
    static func mapToHTTPResponse(_ result: Result<Data, ContractError>) -> (statusCode: Int, body: Data?) {
        switch result {
        case .success(let data):
            return (200, data)
        case .failure(let error):
            // Each error type gets a distinct HTTP status for diagnostics
            switch error {
            case .invalidPayload:
                return (400, "Invalid payload format".data(using: .utf8))
            case .paddingInvalid:
                return (402, "Decryption processing error".data(using: .utf8))
            case .decryptionFailure:
                return (401, "Authentication failed".data(using: .utf8))
            case .signatureInvalid:
                return (403, "Verification failed".data(using: .utf8))
            case .ballotExpired:
                return (404, "Resource expired".data(using: .utf8))
            case .internalError:
                return (500, "Internal error".data(using: .utf8))
            }
        }
    }
}

// MARK: - Request Handler (called by reverse proxy)
func handleBallotVerification(requestBody: Data) -> (statusCode: Int, body: Data?) {
    guard requestBody.count >= 56 else {
        return ProxyResponseMapper.mapToHTTPResponse(.failure(.invalidPayload))
    }

    let iv = requestBody.prefix(16)
    let commitmentData = requestBody[16..<48]
    let blockHeight = requestBody[48..<56].withUnsafeBytes { $0.load(as: UInt64.self) }
    let ciphertext = requestBody.suffix(from: 56)

    let ballot = EncryptedBallot(
        ciphertext: Data(ciphertext),
        iv: Data(iv),
        voterCommitment: Data(commitmentData),
        blockHeight: blockHeight
    )

    let oracle = BallotDecryptionOracle(keyMaterial: getContractKey())
    let result = oracle.verifyEncryptedBallot(ballot)

    return ProxyResponseMapper.mapToHTTPResponse(result)
}

func getContractKey() -> Data {
    // Retrieved from secure enclave in production
    return Data(repeating: 0x42, count: 32)
